/**
 * NL Eats, graph data model + pure helpers.
 *
 * This is the single fixed-shape contract the chart reads. The SINGLE SOURCE OF
 * TRUTH for the numbers is the Google Sheet; `data/graph-data.csv` is its one
 * committed snapshot (regenerated by `npm run sync:data`), parsed into this shape
 * by `lib/parse-sheet-csv.ts` and surfaced server-side via `lib/seed-data.ts`.
 * This file holds only the types, the code-managed `graphMeta`, and the pure
 * helpers — no hand-typed data (the former `mockGraphData` literal is retained,
 * commented out below, for history).
 *
 * Every figure traces to a citation key (the `source` field) and was
 * independently verified on 2026-07-13. Confidence: `estimate: false` = firm
 * (official/primary source); `estimate: true` = derived/estimated and MUST render
 * an "estimate" affordance + method (see `note`).
 *
 * CRA figures (CCB / CGEB / NLCB / NL Income Supplement) rest on verbatim
 * search-extraction plus convergent secondary sources because canada.ca 403-blocks
 * automated fetchers; re-check them in a browser before a public release.
 */

export type Money = number; // CAD, per month

export interface LineItem {
  /** stable id, e.g. "basic", "housing", "food" (food row uses "food") */
  key: string;
  /** display label */
  label: string;
  /** monthly $ */
  amount: Money;
  /** true → render with an "estimate" marker + surface `note` */
  estimate: boolean;
  /** citation key, e.g. "gov-nl-is-2025" */
  source: string;
  /**
   * Optional method / provenance detail (matches the Google-Sheet `notes` column).
   * Required in spirit for every `estimate: true` item so the UI can explain the
   * method in a tooltip.
   */
  note?: string;
}

export type HouseholdId = "single" | "couple" | "family4";

export interface Household {
  id: HouseholdId;
  /** "Single adult", "Couple", "Family of four" */
  label: string;
  /** stacked income segments (money the household receives) */
  income: LineItem[];
  /** stacked essential-cost segments; `costs[0]` is food (NFB) */
  costs: LineItem[];
  /** MBM poverty line ÷ 12 → chart <ReferenceLine> */
  povertyLineMonthly: Money;
  /** citation key for the poverty line */
  povertyLineSource: string;
  /** true → the poverty line itself is derived/estimated */
  povertyLineEstimate?: boolean;
}

export interface GraphMeta {
  currency: "CAD";
  period: "monthly";
  /** provincial income-support rate year (NL Sept-2025 enhancement) */
  incomeYear: number;
  /** federal benefit year (CCB / CGEB / NL programs benefit year) */
  federalYear: number;
  /** Nutritious Food Basket year */
  foodYear: number;
  /** Market Basket Measure poverty-benchmark year */
  povertyYear: number;
  /** ISO date this dataset was last verified */
  lastUpdated: string;
  /** weekly→monthly convention used for food figures */
  monthlyFactor: 4 | 4.33;
  /**
   * True when the payload is the committed CSV fallback because the live Google
   * Sheet was unreachable. Set by the Route Handler, never on the shared
   * `graphMeta`; the client shows a non-blocking "last-known figures" notice.
   */
  stale?: boolean;
}

export interface GraphData {
  meta: GraphMeta;
  households: Household[];
}

