/**
 * Dataset `meta`. This is NOT a per-row Google-Sheet field (the Sheet has no meta
 * columns), so it lives in code and is bumped on a data refresh. Shared by the mock
 * AND the CSV parser (`lib/parse-sheet-csv.ts`) so they agree.
 */
export const graphMeta: GraphMeta = {
  currency: "CAD",
  period: "monthly",
  incomeYear: 2025, // NL Income-Support rates: Sept-2025 enhancement
  federalYear: 2026, // federal benefit year (CCB/CGEB 2026-27)
  foodYear: 2024, // Nutritious Food Basket
  povertyYear: 2024, // Maytree "Welfare in Canada" / MBM
  lastUpdated: "2026-07-14",
  monthlyFactor: 4.33,
};

