// ── pure helpers (exported so the Vitest suites can import & assert them) ──

/** Sum the monthly amounts of a set of line items. */
export function sumLineItems(items: LineItem[]): Money {
  return items.reduce((total, item) => total + item.amount, 0);
}

/**
 * Shortfall = total income − total essential costs. Negative → deficit
 * (status/red styling on the client).
 *
 * Labelling caveat: `costs` is currently food-only while `income` includes a
 * housing/rental line earmarked for rent, so this value is "what's left AFTER
 * healthy food, for rent + heat + everything else", NOT a disposable surplus.
 * The UI must frame it that way, never a bare "money left".
 */
export function computeShortfall(income: LineItem[], costs: LineItem[]): Money {
  return sumLineItems(income) - sumLineItems(costs);
}

/** Convenience lookup by household id. */
export function getHousehold(
  data: GraphData,
  id: HouseholdId,
): Household | undefined {
  return data.households.find((h) => h.id === id);
}

/** Deep income poverty threshold: below 75% of the Market Basket Measure line. */
export const DEEP_POVERTY_FRACTION = 0.75;

/**
 * A household's total income as a share of its own MBM poverty line (1 = at the
 * line). This is the axis of the cross-household comparison chart and mirrors
 * Maytree's "welfare income vs. the Market Basket Measure" framing: the income
 * total includes the rent-earmarked housing benefit, exactly as Maytree counts
 * total welfare income. Returns 0 when the line is non-positive (guards ÷0).
 */
export function povertyLineShare(household: Household): number {
  if (household.povertyLineMonthly <= 0) return 0;
  return sumLineItems(household.income) / household.povertyLineMonthly;
}

/**
 * Count, across the modelled households, how many fall below the MBM poverty line
 * and how many are in *deep* poverty (< 75% of the line). Derived, never hardcoded,
 * so the on-page poverty claim can't drift from the households actually shown.
 * Exported for the Sources & methodology copy and for tests.
 */
export function povertyStats(households: Household[]): {
  total: number;
  belowLine: number;
  deepPoverty: number;
} {
  const belowLine = households.filter(
    (h) => sumLineItems(h.income) < h.povertyLineMonthly,
  ).length;
  const deepPoverty = households.filter(
    (h) =>
      sumLineItems(h.income) < DEEP_POVERTY_FRACTION * h.povertyLineMonthly,
  ).length;
  return { total: households.length, belowLine, deepPoverty };
}
